//! `pin-refresh`: rewrites every World pin, its identity file and the preproduction manifest to the
//! values of the tree, so a stale or merge-conflicted pin is regenerated by one command instead of
//! copying the digests from two `pin-check` refusals by hand. Each pin keeps its reviewed
//! `entry_start`; `pin-check` stays the gate that proves the result.

use std::fs;
use std::path::Path;

use oteryn_world_bundle_compiler::Error;
use serde_json::{Value, json};

use super::{
    PIN_SCHEMA, PINS, Pin, build_twice, derive_identity, hex, identity_text, inputs_digest, read,
};

/// The World whose bundle the preproduction topology manifest serves, and that manifest.
const PREPROD_MANIFEST: (&str, &str) = ("oteryn", "deploy/synology-game/preprod-topology.toml");

/// Refreshes every pin from the tree's staged inputs (`inputs_digest` reads the git index, so the
/// inputs are staged first). Returns the JSON summary.
pub(super) fn run(root: &Path) -> Result<Value, Error> {
    let pins = root.join(PINS);
    let tree = inputs_digest(root)?;
    let mut reports = Vec::new();
    for slug in super::pin_slugs(&pins)? {
        let fail = |what: String| Error::Format(format!("pin {slug}: {what}"));
        let path = pins.join(format!("{slug}.json"));
        let mut old: Value =
            serde_json::from_slice(&read(&path)?).map_err(|e| fail(e.to_string()))?;
        if old["schema"] == "OTERYN_WORLD_PIN/v1" {
            // Refresh is the migration path; pin-check accepts only v2.
            if let Some(fields) = old.as_object_mut() {
                fields.remove("inputs_digest");
            }
        } else if old["schema"] != PIN_SCHEMA {
            return Err(fail(format!("unsupported schema; expected {PIN_SCHEMA}")));
        }
        let old: Pin = serde_json::from_value(old).map_err(|e| fail(e.to_string()))?;
        let identity = derive_identity(root, &slug)?;
        write(
            &pins.join(format!("{slug}.identity.json")),
            &identity_text(&identity)?,
        )?;
        let bytes = build_twice(root, &identity)?;
        let pin = Pin {
            schema: PIN_SCHEMA.to_owned(),
            digest: hex(&bytes[bytes.len() - 32..]),
            project_format_version: identity.project_format_version.clone(),
            world_schema_version: identity.world_schema_version.clone(),
            content_revision: identity.content_revision.clone(),
            production: false,
            entry_start: old.entry_start,
        };
        let text = serde_json::to_string_pretty(&pin).map_err(|e| fail(e.to_string()))? + "\n";
        write(&path, &text)?;
        if slug == PREPROD_MANIFEST.0 {
            refresh_manifest(&root.join(PREPROD_MANIFEST.1), &old, &pin)?;
        }
        reports.push(json!({"world": slug, "digest": pin.digest, "previous": old.digest}));
    }
    Ok(json!({"inputs_digest": tree, "pins": reports}))
}

/// Points the manifest's `[world_bundle]` table and `[readiness] map_revision` at the new pin.
fn refresh_manifest(path: &Path, old: &Pin, new: &Pin) -> Result<(), Error> {
    let text = String::from_utf8(read(path)?)
        .map_err(|_| Error::Format(format!("{}: not UTF-8", path.display())))?;
    let mut table = String::new();
    let mut out = String::with_capacity(text.len());
    for line in text.split_inclusive('\n') {
        if line.starts_with('[') {
            table = line.trim().to_owned();
        }
        let mut line = line.replace(&old.digest, &new.digest);
        if table == "[world_bundle]" {
            for (key, value) in [
                ("project_format_version", &new.project_format_version),
                ("world_schema_version", &new.world_schema_version),
                ("content_revision", &new.content_revision),
            ] {
                if line.starts_with(&format!("{key} = ")) {
                    line = format!("{key} = \"{value}\"\n");
                }
            }
        }
        out.push_str(&line);
    }
    write(path, &out)
}

fn write(path: &Path, text: &str) -> Result<(), Error> {
    fs::write(path, text).map_err(|e| Error::Format(format!("{}: {e}", path.display())))
}
